def is_permutation_matrix(m):
    n = len(m)
    for row in m:
        if len(row) != n:
            return False
    for row in m:
        if any(v not in (0, 1) for v in row):
            return False
        if sum(row) != 1:
            return False
    for j in range(n):
        if sum(m[i][j] for i in range(n)) != 1:
            return False
    return True

