    return sorted(k for k, c in cnt.items() if c == 1)

def is_balanced_parentheses(s):
    depth = 0
    for ch in s:
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

