def add_days(date, n):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def dim(y, m):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if m == 2 and is_leap(y):
            return 29
        return lengths[m-1]
    y, m, d = date
    d += n
    while d < 1:
        m -= 1
        if m < 1:
            m = 12
            y -= 1
        d += dim(y, m)
    while d > dim(y, m):
        d -= dim(y, m)
        m += 1
        if m > 12:
            m = 1
            y += 1
    return (y, m, d)

def rank_normalize_scores(scores):
    n = len(scores)
    if n <= 1:
        return [0.0 for _ in scores]
    s = sorted(scores)
    rank = {}
    for i, v in enumerate(s):
        if v not in rank:
            rank[v] = i
    return [round(rank[v] / (n - 1), 4) for v in scores]
